import{_ as l,C as o,o as t,c as n,j as i,E as s,a as e,a2 as h}from"./chunks/framework.C21TwvGF.js";const b=JSON.parse(`{"title":"5-hafta","description":"","frontmatter":{"title":"5-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"9-sinf (IoT)","link":"/9-sinf-iot/"},"n":5,"bob":"III-bob · Mikrokontrollerlar va IoT qurilmalari (Arduino, ESP8266, ESP32)","lessons":[{"g":13,"title":"IoT uchun asosiy qurilmalar: Arduino va Raspberry Pi taqqosi","lead":"Biri — bitta ishni yillar davomida to'xtovsiz bajaradigan «tirishqoq ishchi», ikkinchisi — kaftga sig'adigan haqiqiy kompyuter. Bugun Arduino va Raspberry Pi'ni yonma-yon qo'yib, qaysi loyihaga qaysi biri kerakligini o'rganamiz.","link":"/9-sinf-iot/hafta-05/dars-1","slide":"/slaydlar/9-sinf-iot/hafta-05/dars-1.html","test":"/slaydlar/9-sinf-iot/hafta-05/dars-1-test.html"},{"g":14,"title":"IoT uchun asosiy qurilmalar: ESP8266 va ESP32 imkoniyatlari","lead":"Tirnoqdek chip, ichida esa Wi-Fi, ba'zan Bluetooth ham. Aqlli rozetka, aqlli lampa va ko'plab «aqlli» uy jihozlari ichida aynan shunday modullar ishlaydi. Bugun ESP8266 va ESP32 bilan tanishamiz.","link":"/9-sinf-iot/hafta-05/dars-2","slide":"/slaydlar/9-sinf-iot/hafta-05/dars-2.html","test":"/slaydlar/9-sinf-iot/hafta-05/dars-2-test.html"},{"g":15,"title":"Mikrokontroller tushunchasi va IoT qurilmalaridagi o'rni (1-qism)","lead":"Kir yuvish mashinasi, mikroto'lqinli pech, televizor pulti, avtomobil tormozi — ularning hammasi ichida kichik «kompyuter» yashirinib ishlaydi. Bu — mikrokontroller. Bugun uning ichida nima borligini va qanday ishlashini bilib olamiz.","link":"/9-sinf-iot/hafta-05/dars-3","slide":"/slaydlar/9-sinf-iot/hafta-05/dars-3.html","test":"/slaydlar/9-sinf-iot/hafta-05/dars-3-test.html"}],"test":"/slaydlar/9-sinf-iot/hafta-05/hafta-test.html"}},"headers":[],"relativePath":"9-sinf-iot/hafta-05/index.md","filePath":"9-sinf-iot/hafta-05/index.md"}`),d={name:"9-sinf-iot/hafta-05/index.md"},u={class:"blk"},m={id:"uyga-vazifa",tabindex:"-1"};function k(y,a,g,c,f,q){const r=o("Icon");return t(),n("div",null,[i("div",u,[i("h2",m,[s(r,{name:"house"}),a[0]||(a[0]=e(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=h('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan. Natijani hujjat (jadval, rasm) yoki Tinkercad/Wokwi havolasi va skrinshotlar bilan topshiring.</p><hr><h3 id="_13-dars-arduino-va-raspberry-pi" tabindex="-1">13-dars: Arduino va Raspberry Pi <a class="header-anchor" href="#_13-dars-arduino-va-raspberry-pi" aria-label="Permalink to &quot;13-dars: Arduino va Raspberry Pi&quot;">​</a></h3><ol><li>Arduino UNO va Raspberry Pi 4 ni 6 mezon bo&#39;yicha taqqoslovchi jadval tuzing: OS, protsessor/RAM, tarmoq, dasturlash tili, energiya, narx.</li><li>Har bir qurilma uchun 2 tadan real IoT loyiha misolini yozing va nega aynan shu qurilma tanlanganini 1 jumlada asoslang.</li><li>Raspberry Pi Pico nega «mikrokompyuter» emas, balki mikrokontroller ekanini 2–3 jumlada tushuntiring.</li></ol><hr><h3 id="_14-dars-esp8266-va-esp32-imkoniyatlari" tabindex="-1">14-dars: ESP8266 va ESP32 imkoniyatlari <a class="header-anchor" href="#_14-dars-esp8266-va-esp32-imkoniyatlari" aria-label="Permalink to &quot;14-dars: ESP8266 va ESP32 imkoniyatlari&quot;">​</a></h3><ol><li>ESP8266 va ESP32 taqqoslash jadvalini tuzing (7 xususiyat: tezlik, yadrolar, Wi-Fi, Bluetooth, GPIO, ADC, UART).</li><li>Wi-Fi&#39;ga ulanish dasturini (<code>WiFi.h</code>) qatorma-qator izohlang; Station va Access Point rejimlariga bittadan misol keltiring.</li><li>3 ta loyihaga mos modulni tanlang va asoslang: (a) Wi-Fi rele; (b) Bluetooth&#39;li qadam sanagich; (c) 5 ta sensorli ob-havo stansiyasi + ekran + bulut.</li><li>Qo&#39;shimcha: Wokwi&#39;da ESP32 Wi-Fi ulanish kodini ishga tushirib, IP va RSSI qiymatlarini skrinshot bilan yuboring.</li></ol><hr><h3 id="_15-dars-mikrokontroller-tushunchasi-1-qism" tabindex="-1">15-dars: Mikrokontroller tushunchasi (1-qism) <a class="header-anchor" href="#_15-dars-mikrokontroller-tushunchasi-1-qism" aria-label="Permalink to &quot;15-dars: Mikrokontroller tushunchasi (1-qism)&quot;">​</a></h3><ol><li>Mikrokontroller va mikroprotsessorni 5 mezon bo&#39;yicha taqqoslovchi jadval tuzing (tuzilishi, vazifasi, tezlik/quvvat, narx, misollar).</li><li>Arduino UNO rasmida ATmega328P, raqamli pinlar (14), analog pinlar (6), 5V/3.3V/GND, USB-B va kvars generatorni belgilang.</li><li>«Tugma → LED» dasturida Input va Output qatorlarini, RAM&#39;dagi o&#39;zgaruvchini va CPU qaror qabul qiladigan qatorni belgilang. Tok o&#39;chib-yonsa nima saqlanishini yozing.</li><li>Uyingizdan ichida mikrokontroller ishlaydigan 5 ta qurilmani toping va har birining «bitta vazifasini» yozing.</li></ol><hr>',11))])])}const p=l(d,[["render",k]]);export{b as __pageData,p as default};
